// Config plugin: settings this project needs to build its Android APK locally on Windows.
// android/ is regenerated by `expo prebuild`, so these live here instead of in the generated files.
const { withAppBuildGradle, withGradleProperties } = require('expo/config-plugins');

// arm64-v8a for real phones, x86_64 for the emulator. Skipping the 32-bit ABIs halves build time.
const ARCHITECTURES = 'arm64-v8a,x86_64';

// Libraries with native screen components (react-native-screens, safe-area-context) compile object
// files at paths over 300 characters. That needs Windows long paths switched on (LongPathsEnabled=1)
// AND a ninja that is long-path aware: CMake 3.22's ninja 1.10 is not, CMake 3.31's ninja 1.12 is.
const CMAKE_VERSION = '3.31.6';

function withArchitectures(config) {
  return withGradleProperties(config, (cfg) => {
    const existing = cfg.modResults.find((item) => item.type === 'property' && item.key === 'reactNativeArchitectures');
    if (existing) {
      existing.value = ARCHITECTURES;
    } else {
      cfg.modResults.push({ type: 'property', key: 'reactNativeArchitectures', value: ARCHITECTURES });
    }
    return cfg;
  });
}

function withCmakeVersion(config) {
  return withAppBuildGradle(config, (cfg) => {
    const gradle = cfg.modResults;
    if (gradle.contents.includes(`version "${CMAKE_VERSION}"`)) return cfg;
    const block = [
      '',
      '    externalNativeBuild {',
      '        cmake {',
      `            version "${CMAKE_VERSION}"`,
      '        }',
      '    }',
    ].join('\n');
    const next = gradle.contents.replace(/(\nandroid\s*\{)/, `$1${block}`);
    if (next === gradle.contents) {
      throw new Error('withLocalAndroidBuild: android { } block not found in app/build.gradle');
    }
    gradle.contents = next;
    return cfg;
  });
}

module.exports = function withLocalAndroidBuild(config) {
  return withCmakeVersion(withArchitectures(config));
};
